import struct

MODEL = r"F:\rawrxd\models\qwen2.5-coder_1.5b-base.gguf"
raw = open(r"F:\rawrxd\evidence\PARITY_2026-10-13\cli_def.out", "rb").read()

# extract the generated bytes between the prompt echo and the timing line
start = raw.find(b"> def\r\n") + len(b"> def\r\n")
end = raw.find(b"\r\n\r\n[ Prompt:", start)
gen = raw[start:end]
rep = []
rep.append("GENERATED_BYTES_HEX=" + gen.hex(" "))
rep.append("GENERATED_UTF8=" + repr(gen))

# load the vocab and find exact byte matches
with open(MODEL, "rb") as fh:
    magic, version, tcount, kvcount = struct.unpack("<4sIQQ", fh.read(24))
    toks = None
    for _ in range(kvcount):
        klen = struct.unpack("<Q", fh.read(8))[0]
        key = fh.read(klen).decode("utf-8", "replace")
        vtype = struct.unpack("<I", fh.read(4))[0]
        if vtype == 8:
            n = struct.unpack("<Q", fh.read(8))[0]
            val = fh.read(n)
        elif vtype == 9:
            etype = struct.unpack("<I", fh.read(4))[0]
            count = struct.unpack("<Q", fh.read(8))[0]
            if etype == 8:
                val = []
                for _ in range(count):
                    n = struct.unpack("<Q", fh.read(8))[0]
                    val.append(fh.read(n))
            else:
                fmtc = {0:("B",1),1:("b",1),2:("H",2),3:("h",2),4:("I",4),
                        5:("i",4),6:("f",4),7:("?",1),10:("Q",8),11:("q",8),
                        12:("d",8)}
                c, esz = fmtc[etype]
                val = list(struct.unpack(f"<{count}{c}", fh.read(esz*count)))
        else:
            fmtc = {0:("B",1),1:("b",1),2:("H",2),3:("h",2),4:("I",4),
                    5:("i",4),6:("f",4),7:("?",1),10:("Q",8),11:("q",8),
                    12:("d",8)}
            c, esz = fmtc[vtype]
            val = struct.unpack(f"<{c}", fh.read(esz))[0]
        if key == "tokenizer.ggml.tokens":
            toks = val

exact = [i for i, t in enumerate(toks) if t == gen]
rep.append("EXACT_TOKEN_MATCHES=" + str(exact))

# single-token candidates of interest
for t in (750, 5290, 304, 1875, 374):
    if 0 <= t < len(toks):
        rep.append(f"token[{t}] bytes={toks[t].hex(' ')} utf8={toks[t]!r}")

# how many tokens does the generated byte string cover?
best = None
for i, t in enumerate(toks):
    if gen.startswith(t) and len(t) > 0:
        if best is None or len(t) > len(toks[best]):
            best = i
rep.append(f"LONGEST_VOCAB_PREFIX_MATCH=token[{best}] "
           f"bytes={toks[best].hex(' ') if best is not None else ''}")

open(r"F:\rawrxd\evidence\PARITY_2026-10-13\cli_def_tok.txt", "w",
     encoding="utf-8").write("\n".join(rep))
print("\n".join(rep))
